import sys
import hashlib

def compute_file_hash(file_path):
    hash_md5 = hashlib.md5()
    try:
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_md5.update(chunk)
    except Exception as e:
        return str(e)
    return hash_md5.hexdigest()

def main():
    file_paths = sys.stdin.read().strip().split('\n')
    hashes = []
    for path in file_paths:
        file_hash = compute_file_hash(path)
        hashes.append((path, file_hash))

    print('<html>')
    print('<head><title>File Hash Manifest</title></head>')
    print('<body>')
    print('<table border="1">')
    print('<tr><th>File Path</th><th>Hash</th></tr>')
    for path, file_hash in hashes:
        print(f'<tr><td>{path}</td><td>{file_hash}</td></tr>')
    print('</table>')
    print('</body>')
    print('</html>')

if __name__ == '__main__':
    main()
